    Definition SVOP : list word :=
      [Z_to_bv 64 ret; getr R 8%bv; getr R 9%bv; getr R 18%bv; getr R 19%bv; getr R 20%bv; getr R 21%bv; Z_to_bv 64 LOC_IMP; Z_to_bv 64 ds].

    Lemma optail : forall (sv9 sv18 sv19 sv20 sv21 sv22 sv23 : word), sv22 = getr R 22%bv -> sv23 = getr R 23%bv ->
      forall A' R3 M1 M3 model' B' (J : Z -> Prop),
        ainv MI A' M3 model' -> mstd model' -> m_fs model' = m_fs model -> m_fds model' = m_fds model -> sx_inv ST s M3 ->
        ds_rep MI A' M3 ds err (len + 24) B' -> blk_xfer B B' (live MI A) (live MI A') -> junk_ok MI A J ->
        eff MI A A' M M3 (sp - S, sp) (fun a => ds_foot ds B a \/ ds_foot ds B' a \/ J a) ->
        agree_on (zwin (sp - 80) sp) M1 M3 -> slots SEGS M1 sp SVOP ->
        getr R3 2%bv = Z_to_bv 64 (sp - 80) -> getr R3 3%bv = getr R 3%bv -> getr R3 4%bv = getr R 4%bv ->
        getr R3 10%bv = Z_to_bv 64 (ds + 8) -> getr R3 8%bv = Z_to_bv 64 ds ->
        getr R3 9%bv = sv9 -> getr R3 18%bv = sv18 -> getr R3 19%bv = sv19 -> getr R3 20%bv = sv20 -> getr R3 21%bv = sv21 ->
        getr R3 22%bv = sv22 -> getr R3 23%bv = sv23 ->
        (forall r, In r [24; 25; 26; 27]%bv -> getr R3 r = getr R r) ->
        mdef M3 (sp - S) S ->
